/* @lc app=leetcode id=2193 lang=kotlin */
class Solution { fun minMovesToMakePalindrome(s: String): Int = s.toCharArray().let { arr -> intArrayOf(0, arr.size - 1, 0).apply { while (this[0] < this[1]) (this[1] downTo this[0] + 1).firstOrNull { arr[it] == arr[this@apply[0]] }.let { k -> if (k == null) arr[this@apply[0]].also { arr[this@apply[0]] = arr[this@apply[0] + 1] }.also { arr[this@apply[0] + 1] = it }.also { this@apply[2]++ } else (k until this@apply[1]).forEach { i -> arr[i].also { arr[i] = arr[i + 1] }.also { arr[i + 1] = it }.also { this@apply[2]++ } }.also { this@apply[0]++ }.also { this@apply[1]-- } } }[2] } }